select set_config('request.jwt.claim.sub','71000000-0000-4000-8000-000000000001',true);set local role authenticated;
do $$declare c uuid:='72000000-0000-4000-8000-000000000001';e uuid:='73000000-0000-4000-8000-000000000001';manager uuid:='73000000-0000-4000-8000-000000000002';schedule uuid;holiday uuid;n integer;begin
