 holiday:=public.save_work_calendar(c,'{"kind":"holiday","date":"2026-09-07","name":"Reviewed fixture holiday","reviewReference":"Reviewed fixture paid holiday"}');
 perform public.save_attendance(c,jsonb_build_array(jsonb_build_object('employeeId',e,'date','2026-09-05','status','Present','checkIn','10:15')),'Actual manual fixture attendance',false);
 n:=public.apply_nonworking_attendance(c,'2026-09-01');
 if n<>8 then raise exception 'FAIL employment-scoped nonworking count: %',n;end if;
 if(select status from public.attendance_records where company_id=c and employee_id=e and date='2026-09-05')<>'Present'then raise exception 'FAIL calendar overwrote attendance';end if;
 if exists(select 1 from public.attendance_records where company_id=c and date<'2026-09-03')or exists(select 1 from public.attendance_records where company_id=c and employee_id=manager)then raise exception 'FAIL calendar outside employment';end if;
 if public.apply_nonworking_attendance(c,'2026-09-01')<>0 then raise exception 'FAIL calendar duplicate rows';end if;
 perform public.save_attendance(c,jsonb_build_array(jsonb_build_object('employeeId',e,'date','2026-09-08','status','Present','checkIn','10:15')),'Initial entry',false);
 if(select scheduled_start from public.attendance_records where company_id=c and employee_id=e and date='2026-09-08')<>'10:00'::time then raise exception 'FAIL scheduled start snapshot';end if;
 perform public.retire_work_calendar(c,'holiday',holiday,1,'Incorrect holiday fixture');
 if(select status from public.attendance_records where company_id=c and employee_id=e and date='2026-09-07')<>'Holiday'then raise exception 'FAIL calendar retirement changed attendance';end if;
 begin perform public.retire_work_calendar(c,'holiday',holiday,1,'Stale retirement');raise exception 'FAIL stale calendar retirement';exception when serialization_failure then null;end;
